def map_phase(documents):
    pairs = []
    for doc_id, text in documents:
        for word in text.lower().split():
            pairs.append((word, 1))
    return pairs

def shuffle_phase(pairs):
    grouped = {}
    for word, count in pairs:
        grouped.setdefault(word, []).append(count)
    return grouped

def reduce_phase(grouped):
    return {word: sum(counts) for word, counts in grouped.items()}

documents = [
    (1, "train model train pipeline"),
    (2, "deploy model monitor model"),
    (3, "train pipeline deploy pipeline"),
]

mapped = map_phase(documents)
shuffled = shuffle_phase(mapped)
reduced = reduce_phase(shuffled)

print("Pares mapeados:", len(mapped))
for word in sorted(reduced):
    print(f"{word}: {reduced[word]}")
